mapper.select:
SELECT * FROM ( SELECT 'REGION' AS type, emd.id AS id, emd.name AS label, CONCAT(sido.name, ' ', sgg.name) AS sublabel, CONCAT('/region/emd/', emd.id) AS path FROM region_emd emd JOIN region_sigungu sgg ON sgg.id = emd.sigungu_id JOIN region_sido sido ON sido.id = sgg.sido_id WHERE emd.name LIKE CONCAT('%', #{q}, '%')
UNION ALL
SELECT 'REGION' AS type, sgg.id AS id, sgg.name AS label, sido.name AS sublabel, CONCAT('/region/sgg/', sgg.id) AS path FROM region_sigungu sgg JOIN region_sido sido ON sido.id = sgg.sido_id WHERE sgg.name LIKE CONCAT('%', #{q}, '%') ) t ORDER BY label LIMIT #{limit}
